phap_ly_dat"],"layout":"2col","always_show":true,"collapsible":false},{"id":"station_proposals_view_s8","color":"#27ae60","emoji":"📋","title":"Thông tin hệ thống","fields":["status","ma_de_xuat","nguoi_de_xuat","sales_quan_ly"],"layout":"2col","always_show":true,"collapsible":false}]}'
